/**
 * BIS SAKSHAM — Contextual AI Assistant
 *
 * This module provides context-aware response templates for the "Ask SAKSHAM"
 * assistant. Responses are deterministic based on product context and question
 * category — NOT generated by a live LLM (demo mode).
 *
 * ARCHITECTURE: AI explains, deterministic engine decides.
 * No compliance facts are invented. All responses reference seeded evidence.
 */

import { getProductById } from './demoData.js';

// ─── RESPONSE TEMPLATES ────────────────────────────────────────────────────────

const GENERAL_RESPONSES = {
  what_is_bis: {
    answer: 'The Bureau of Indian Standards (BIS) is the national body responsible for formulating and publishing Indian Standards (IS). BIS also administers the product certification (ISI Mark) scheme and hallmarking for gold and silver jewellery.',
    evidence: null,
    confidence: 'HIGH',
    trustLabel: 'BIS Source',
  },
  what_is_qco: {
    answer: 'A Quality Control Order (QCO) is a government notification (under the BIS Act or relevant ministry) that makes BIS certification mandatory for specified products. Products covered under a QCO cannot be sold in India without carrying the ISI Mark.',
    evidence: { source: 'BIS', document: 'BIS Act 2016, Section 16' },
    confidence: 'HIGH',
    trustLabel: 'BIS Source',
  },
  what_is_isi: {
    answer: 'The ISI Mark (Indian Standards Institution Mark) is a BIS certification mark. It signifies that the product has been tested and certified to meet the applicable Indian Standard. For products covered under QCOs, the ISI Mark is legally mandatory.',
    evidence: { source: 'BIS', document: 'BIS Product Certification Scheme Guidelines' },
    confidence: 'HIGH',
    trustLabel: 'BIS Source',
  },
  what_is_nabl: {
    answer: 'NABL (National Accreditation Board for Testing and Calibration Laboratories) is the accreditation body for testing and calibration laboratories in India. NABL accreditation assures the technical competence of a laboratory. BIS typically requires test reports from NABL-accredited laboratories for product certification.',
    evidence: null,
    confidence: 'HIGH',
    trustLabel: 'AI-assisted',
  },
};

// ─── PRODUCT-SPECIFIC RESPONSE GENERATORS ─────────────────────────────────────

export function generateContextualResponse(question, productId) {
  const product = productId ? getProductById(productId) : null;
  const lowerQ = question.toLowerCase();

  // ── General BIS questions ──
  if (lowerQ.includes('what is bis') || lowerQ.includes('bureau of indian standards')) {
    return GENERAL_RESPONSES.what_is_bis;
  }
  if (lowerQ.includes('qco') || lowerQ.includes('quality control order')) {
    return GENERAL_RESPONSES.what_is_qco;
  }
  if (lowerQ.includes('isi mark') || lowerQ.includes('isi certification')) {
    return GENERAL_RESPONSES.what_is_isi;
  }
  if (lowerQ.includes('nabl')) {
    return GENERAL_RESPONSES.what_is_nabl;
  }

  // ── Product-specific questions ──
  if (!product) {
    return {
      answer: 'Please select a product to get product-specific compliance guidance. You can analyze a product using the "Start Compliance Check" button or from your compliance workspace.',
      evidence: null,
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // Missing evidence question
  if (lowerQ.includes('missing') || lowerQ.includes('what evidence') || lowerQ.includes('what is missing')) {
    const missingReqs = product.requirements.filter(r => r.status === 'MISSING');
    if (missingReqs.length === 0) {
      return {
        answer: `All requirements for ${product.name} currently have evidence on file. However, ${product.requirements.filter(r => r.status === 'REVIEW').length} requirement(s) are under review and may need additional documentation.`,
        evidence: null,
        confidence: 'HIGH',
        trustLabel: 'AI-assisted',
      };
    }
    const missingList = missingReqs.map(r => `• **${r.title}** (${r.type})`).join('\n');
    return {
      answer: `For **${product.name}**, the following ${missingReqs.length} requirement(s) are currently missing evidence:\n\n${missingList}\n\nThe most critical missing item is the **Energy Efficiency Test (BEE Star Rating)**, which is required before commercial sale.`,
      evidence: {
        source: 'DEMO DATA',
        document: 'BIS SAKSHAM Compliance Analysis',
        note: 'Based on seeded compliance data for demonstration purposes.',
      },
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // Next test question
  if (lowerQ.includes('next test') || lowerQ.includes('what test') || lowerQ.includes('which test')) {
    const missingTests = product.tests.filter(t => t.status === 'MISSING');
    if (missingTests.length === 0) {
      return {
        answer: `All identified tests for ${product.name} have been completed or are in progress. Check the Compliance Passport for certification application status.`,
        evidence: null,
        confidence: 'HIGH',
        trustLabel: 'AI-assisted',
      };
    }
    const nextTest = missingTests[0];
    return {
      answer: `The next required test for **${product.name}** is:\n\n**${nextTest.name}**\n${nextTest.purpose || ''}\n\nThis test is required by: ${nextTest.standard}\n\nRecommended laboratory: CPRI-CPTL, Bengaluru (covers all outstanding tests).`,
      evidence: {
        source: 'DEMO DATA',
        document: nextTest.standard,
        note: 'Seeded demonstration data.',
      },
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // Why is a requirement applicable
  if (lowerQ.includes('why') && (lowerQ.includes('applicable') || lowerQ.includes('required') || lowerQ.includes('mandatory'))) {
    return {
      answer: `Requirements for **${product.name}** are determined by:\n\n1. **Indian Standards (IS)** — Applicable standards identified based on product category (${product.category})\n2. **Quality Control Order (QCO)** — ${product.qcos[0]?.title || 'Applicable QCO'} makes ISI certification mandatory\n3. **Energy regulations** — BEE requirements apply to energy-consuming appliances\n\nThe deterministic rule engine matches product attributes to applicable requirements. AI explains but does not determine compliance truth.`,
      evidence: {
        source: 'BIS',
        document: product.standards[0]?.document || 'Applicable IS Standard',
        note: 'Applicability determined from seeded BIS metadata. Verify against current official BIS sources.',
      },
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // What changed / recent changes
  if (lowerQ.includes('what changed') || lowerQ.includes('update') || lowerQ.includes('amendment')) {
    const changes = product.changeEvents;
    if (changes.length === 0) {
      return {
        answer: `No recent change events have been identified for **${product.name}** in the demonstration dataset. Check the BIS Updates section for the latest regulatory changes.`,
        evidence: null,
        confidence: 'MEDIUM',
        trustLabel: 'AI-assisted',
      };
    }
    const change = changes[0];
    return {
      answer: `⚠ **DEMO CHANGE EVENT** — A proposed change has been detected:\n\n**${change.title}**\n\n${change.description}\n\nProposed effective date: ${change.effectiveDate}\nImpact level: ${change.impactLevel}\n\nRecommended action: ${change.action}`,
      evidence: {
        source: 'DEMO DATA',
        document: change.source,
        note: 'This is a demonstration change event. Verify against official government notifications.',
      },
      confidence: 'HIGH',
      trustLabel: 'DEMO DATA',
    };
  }

  // What should I do next
  if (lowerQ.includes('what should i do') || lowerQ.includes('next step') || lowerQ.includes('what next')) {
    const summary = product.complianceSummary;
    if (summary.missing === 0 && summary.review === 0) {
      return {
        answer: `**${product.name}** has all requirements satisfied. The next step is to apply for BIS Product Certification (ISI Mark licence) through the official BIS portal.`,
        evidence: { source: 'BIS', document: 'BIS Product Certification Application Guidelines' },
        confidence: 'HIGH',
        trustLabel: 'AI-assisted',
      };
    }
    return {
      answer: `For **${product.name}**, the recommended next steps are:\n\n1. **Complete missing tests** — Schedule Energy Efficiency Test at CPRI Bengaluru (highest priority)\n2. **Complete marking declaration** — Finalize the product marking compliance document\n3. **Apply for ISI Mark** — Submit BIS certification application once all tests are complete\n\nEnsure all test reports are from NABL-accredited, BIS-recognized laboratories.`,
      evidence: {
        source: 'DEMO DATA',
        document: 'BIS SAKSHAM Compliance Analysis',
        note: 'Recommendations based on seeded compliance data. Verify against current official BIS requirements.',
      },
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // Explain a requirement simply
  if (lowerQ.includes('explain') || lowerQ.includes('what does') || lowerQ.includes('what is the')) {
    return {
      answer: `I can explain requirements for **${product.name}**. Please select a specific requirement from the Requirement Matrix and click "Ask SAKSHAM" for a detailed explanation, or type your specific question about a requirement.`,
      evidence: null,
      confidence: 'MEDIUM',
      trustLabel: 'AI-assisted',
    };
  }

  // Show source
  if (lowerQ.includes('source') || lowerQ.includes('evidence') || lowerQ.includes('where')) {
    return {
      answer: `Sources for **${product.name}** compliance information:\n\n${product.standards.map(s => `• **${s.number}** — ${s.title}`).join('\n')}\n\nClick any requirement in the Requirement Matrix to open the Evidence Drawer with full source documentation.`,
      evidence: {
        source: 'BIS',
        document: product.standards[0]?.document,
        note: 'DEMO DATA — for demonstration purposes.',
      },
      confidence: 'HIGH',
      trustLabel: 'AI-assisted',
    };
  }

  // Default / fallback
  return {
    answer: `I can help you understand compliance requirements for **${product.name}**. Try asking:\n\n• "What evidence is missing?"\n• "What test do I need next?"\n• "Why is this requirement applicable?"\n• "What changed recently?"\n• "What should I do next?"\n\nFor compliance-critical decisions, always verify against official BIS sources.`,
    evidence: null,
    confidence: 'MEDIUM',
    trustLabel: 'AI-assisted',
  };
}

// ─── SUGGESTED QUESTIONS ───────────────────────────────────────────────────────

export function getSuggestedQuestions(productId) {
  if (!productId) {
    return [
      'What is BIS and what does it do?',
      'What is a Quality Control Order (QCO)?',
      'What is the ISI Mark?',
      'What is NABL accreditation?',
    ];
  }

  return [
    'What evidence is missing?',
    'What test do I need next?',
    'Why is this requirement applicable?',
    'What changed recently?',
    'What should I do next?',
    'Show me the sources for these requirements.',
  ];
}

// ─── PRODUCT INTERVIEW QUESTIONS ───────────────────────────────────────────────

/**
 * Generate progressive clarification questions for a product.
 * Returns only the most important unanswered questions.
 */
export function generateClarificationQuestions(extractedAttributes) {
  const questions = [];

  if (!extractedAttributes.intendedUse) {
    questions.push({
      id: 'q-use',
      question: 'What is the intended use of this product?',
      type: 'CHOICE',
      options: ['Domestic', 'Commercial', 'Both (Domestic & Commercial)'],
      field: 'intendedUse',
      priority: 1,
    });
  }

  if (!extractedAttributes.capacity) {
    questions.push({
      id: 'q-capacity',
      question: 'What is the storage capacity of the water heater?',
      type: 'CHOICE',
      options: ['Up to 15 L', '15–25 L', '25–50 L', 'Above 50 L', 'Not applicable'],
      field: 'capacity',
      priority: 2,
    });
  }

  if (!extractedAttributes.voltage) {
    questions.push({
      id: 'q-voltage',
      question: 'What is the power supply rating?',
      type: 'CHOICE',
      options: ['220–240 V AC, 50 Hz (Standard India)', '110–120 V AC', 'Both 110V and 220V', 'Other'],
      field: 'voltage',
      priority: 3,
    });
  }

  return questions.slice(0, 2); // Return only top 2 most important
}
